-- Run manually in Supabase SQL Editor after the EUR migration.
-- Six Maison products: provisional 10 EUR each, stock 0 until supplied.
-- Re-runnable: preserves existing dashboard prices, stock, copy and images.
begin;
insert into public.collections (slug, name, description, status, color)
values ('home', 'Produits Maison', 'Senteurs et objets pour vos rituels de maison.', 'live', '#b18a58')
on conflict (slug) do nothing;

insert into public.products (sku, slug, name, description, price_eur, currency, stock_quantity, status, image_url, metadata)
values
('MLZ-OR-RD-100', 'diffuseur-fleur-orientale', 'Diffuseur Fleur orientale', 'Un diffuseur à bâtonnets Fleur orientale, dans un flacon décoré d’une choucha dorée. 100 ml pour parfumer votre intérieur.', 10.00, 'EUR', 0, 'active', '/products/maison/diffuseur-fleur-orientale.png', '{"productType":"reed-diffuser","fragrance":"fleur-orientale","scent":"Fleur orientale","ritual":"home","volumeMl":100,"size":"100 ML","imagePresentation":"photograph","withArgan":false,"localized":{"name":{"fr":"Diffuseur Fleur orientale","en":"Oriental Flower Reed Diffuser","ar":"ناشر عطر الزهرة الشرقية"},"description":{"fr":"Un diffuseur à bâtonnets Fleur orientale, dans un flacon décoré d’une choucha dorée. 100 ml pour parfumer votre intérieur.","en":"An Oriental Flower reed diffuser in a patterned bottle with a golden tassel. 100 ml for your home.","ar":"ناشر بعيدان بعطر الزهرة الشرقية في قارورة مزخرفة بشوشة ذهبية. 100 مل لتعطير المنزل."},"howToUse":{"fr":"Utiliser uniquement selon les indications de l’étiquette. Tenir hors de portée des enfants, à l’écart des flammes et des surfaces fragiles. Ne pas appliquer sur la peau.","en":"Use only as directed on the label. Keep out of reach of children, away from flames and delicate surfaces. Do not apply to skin.","ar":"يُستخدم وفق إرشادات الملصق فقط. يُحفظ بعيداً عن الأطفال واللهب والأسطح الحساسة. لا يُوضع على البشرة."}}}'::jsonb),
('MLZ-FL-HF-100', 'eau-maison-fleur-de-lin', 'Eau de Maison Fleur de Lin', 'Une eau de maison Fleur de Lin en flacon de 100 ml, habillé de motifs bleus et d’une choucha dorée.', 10.00, 'EUR', 0, 'active', '/products/maison/eau-maison-fleur-de-lin.png', '{"productType":"home-fragrance","fragrance":"fleur-de-lin","scent":"Fleur de Lin","ritual":"home","volumeMl":100,"size":"100 ML","imagePresentation":"photograph","withArgan":false,"localized":{"name":{"fr":"Eau de Maison Fleur de Lin","en":"Flax Flower Home Fragrance","ar":"عطر المنزل زهرة الكتان"},"description":{"fr":"Une eau de maison Fleur de Lin en flacon de 100 ml, habillé de motifs bleus et d’une choucha dorée.","en":"A 100 ml Flax Flower home fragrance in a blue patterned bottle with a golden tassel.","ar":"عطر للمنزل بزهرة الكتان في قارورة سعة 100 مل، مزينة بنقوش زرقاء وشوشة ذهبية."},"howToUse":{"fr":"Parfum d’intérieur : suivre les indications de l’étiquette. Ne pas appliquer sur la peau. Tenir loin des flammes et hors de portée des enfants.","en":"Home fragrance: follow the label directions. Do not apply to skin. Keep away from flames and out of reach of children.","ar":"عطر منزلي: تُتبع إرشادات الملصق. لا يُوضع على البشرة. يُحفظ بعيداً عن اللهب ومتناول الأطفال."}}}'::jsonb),
('MLZ-SE-BU-50', 'huile-bruler-serghina', 'Huile à brûler Serghina', 'L’huile à brûler Serghina en flacon compte-gouttes de 50 ml, orné de détails métalliques travaillés.', 10.00, 'EUR', 0, 'active', '/products/maison/huile-bruler-serghina.png', '{"productType":"burner-oil","fragrance":"serghina","scent":"Serghina","ritual":"home","volumeMl":50,"size":"50 ML","imagePresentation":"photograph","withArgan":false,"localized":{"name":{"fr":"Huile à brûler Serghina","en":"Serghina Burner Oil","ar":"زيت السرغينة للتبخير"},"description":{"fr":"L’huile à brûler Serghina en flacon compte-gouttes de 50 ml, orné de détails métalliques travaillés.","en":"Serghina burner oil in a 50 ml dropper bottle with ornate metallic details.","ar":"زيت السرغينة للتبخير في قارورة قطّارة سعة 50 مل مزينة بتفاصيل معدنية منقوشة."},"howToUse":{"fr":"Réservée à la diffusion, selon les indications de l’étiquette et d’un brûle-parfum compatible. Ne pas ingérer ni appliquer sur la peau. Ne jamais laisser une flamme sans surveillance.","en":"For diffusion only, following the label and compatible burner instructions. Do not ingest or apply to skin. Never leave a flame unattended.","ar":"للتبخير فقط وفق إرشادات الملصق ومبخرة متوافقة. لا يُبتلع ولا يُوضع على البشرة. لا تُترك الشعلة دون مراقبة."}}}'::jsonb),
('MLZ-FR-RW-100', 'eau-de-rose-maison', 'Eau de rose', 'Notre eau de rose en flacon de 100 ml, habillé de motifs roses et d’une choucha dorée. Un soin pour la peau, distinct de nos parfums d’intérieur.', 10.00, 'EUR', 0, 'active', '/products/maison/eau-de-rose-maison.png', '{"productType":"rose-water","fragrance":"fleur-de-rose","scent":"Fleur de Rose","ritual":"home","volumeMl":100,"size":"100 ML","imagePresentation":"photograph","withArgan":false,"localized":{"name":{"fr":"Eau de rose","en":"Rose Water","ar":"ماء الورد"},"description":{"fr":"Notre eau de rose en flacon de 100 ml, habillé de motifs roses et d’une choucha dorée. Un soin pour la peau, distinct de nos parfums d’intérieur.","en":"Our rose water in a 100 ml pink patterned bottle with a golden tassel. A skincare product, distinct from our home fragrances.","ar":"ماء الورد في قارورة سعة 100 مل بنقوش وردية وشوشة ذهبية. منتج للعناية بالبشرة، وليس عطراً للمنزل."},"howToUse":{"fr":"Usage cosmétique externe uniquement, conformément aux indications de l’étiquette. Éviter le contact avec les yeux.","en":"For external cosmetic use only, following the label directions. Avoid contact with eyes.","ar":"للاستخدام التجميلي الخارجي فقط وفق إرشادات الملصق. يُتجنب ملامسة العينين."}}}'::jsonb),
('MLZ-SP-OB-0', 'brule-parfum-ceramique', 'Brûle-parfum en céramique', 'Un brûle-parfum en céramique beige mouchetée, avec une coupelle supérieure et une ouverture pour bougie chauffe-plat.', 10.00, 'EUR', 0, 'active', '/products/maison/brule-parfum-ceramique.png', '{"productType":"oil-burner","fragrance":"sans-parfum","scent":"Céramique","ritual":"home","volumeMl":0,"size":"1 pièce","imagePresentation":"photograph","withArgan":false,"localized":{"name":{"fr":"Brûle-parfum en céramique","en":"Ceramic Oil Burner","ar":"مبخرة خزفية"},"description":{"fr":"Un brûle-parfum en céramique beige mouchetée, avec une coupelle supérieure et une ouverture pour bougie chauffe-plat.","en":"A speckled beige ceramic oil burner with an upper bowl and an opening for a tea light.","ar":"مبخرة من الخزف البيج المنقط، بوعاء علوي وفتحة لشمعة صغيرة."},"howToUse":{"fr":"Poser sur une surface stable et résistante à la chaleur. Suivre les instructions du parfum utilisé. Ne jamais laisser une bougie allumée sans surveillance. Laisser refroidir avant manipulation.","en":"Place on a stable, heat-resistant surface. Follow the fragrance instructions. Never leave a lit candle unattended. Allow to cool before handling.","ar":"تُوضع على سطح ثابت ومقاوم للحرارة. تُتبع إرشادات العطر المستخدم. لا تُترك شمعة مشتعلة دون مراقبة. تُترك لتبرد قبل لمسها."}}}'::jsonb),
('MLZ-FR-HF-100', 'eau-maison-fleur-de-rose', 'Eau de Maison Fleur de Rose', 'Une eau de maison Fleur de Rose en flacon de 100 ml, aux motifs roses et rouges, accompagnée de sa choucha dorée.', 10.00, 'EUR', 0, 'active', '/products/maison/eau-maison-fleur-de-rose.png', '{"productType":"home-fragrance","fragrance":"fleur-de-rose","scent":"Fleur de Rose","ritual":"home","volumeMl":100,"size":"100 ML","imagePresentation":"photograph","withArgan":false,"localized":{"name":{"fr":"Eau de Maison Fleur de Rose","en":"Rose Flower Home Fragrance","ar":"عطر المنزل زهرة الورد"},"description":{"fr":"Une eau de maison Fleur de Rose en flacon de 100 ml, aux motifs roses et rouges, accompagnée de sa choucha dorée.","en":"A 100 ml Rose Flower home fragrance in a pink and red patterned bottle with a golden tassel.","ar":"عطر للمنزل بزهرة الورد في قارورة سعة 100 مل بنقوش وردية وحمراء وشوشة ذهبية."},"howToUse":{"fr":"Parfum d’intérieur : suivre les indications de l’étiquette. Ne pas appliquer sur la peau. Tenir loin des flammes et hors de portée des enfants.","en":"Home fragrance: follow the label directions. Do not apply to skin. Keep away from flames and out of reach of children.","ar":"عطر منزلي: تُتبع إرشادات الملصق. لا يُوضع على البشرة. يُحفظ بعيداً عن اللهب ومتناول الأطفال."}}}'::jsonb)
on conflict (sku) do nothing;

insert into public.collection_products (collection_id, product_id, position)
select c.id, p.id, a.position from public.collections c
cross join (values ('MLZ-OR-RD-100', 1), ('MLZ-FL-HF-100', 2), ('MLZ-SE-BU-50', 3), ('MLZ-FR-RW-100', 4), ('MLZ-SP-OB-0', 5), ('MLZ-FR-HF-100', 6)) a(sku, position)
join public.products p on p.sku = a.sku
where c.slug = 'home'
on conflict (collection_id, product_id) do nothing;
commit;
